-- ARC server-authoritative progression structural foundation.
-- This migration creates no user progression and does not alter legacy stats/habits.

begin;

create extension if not exists pgcrypto;

create table public.arc_progress_state (
  user_id uuid primary key references auth.users(id) on delete cascade,
  timezone text not null default 'UTC' check (char_length(timezone) between 1 and 255),
  cutover_arc_day date,
  last_processed_arc_day date,
  active_catalog_version text not null default 'arc_tasks_v1',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (last_processed_arc_day is null or cutover_arc_day is null or last_processed_arc_day >= cutover_arc_day)
);

create table public.arc_user_stats (
  user_id uuid not null references auth.users(id) on delete cascade,
  stat_id text not null check (char_length(stat_id) between 1 and 128),
  stat_kind text not null check (stat_kind in ('canonical', 'custom')),
  canonical_stat_key text,
  display_name text not null check (char_length(display_name) between 1 and 60),
  emoji text not null check (char_length(emoji) between 1 and 32),
  current_value smallint not null check (current_value between 0 and 100),
  start_value smallint check (start_value between 0 and 99),
  sort_order integer not null check (sort_order >= 0),
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, stat_id),
  check (
    (stat_kind = 'canonical'
      and canonical_stat_key is not null
      and canonical_stat_key in ('wissen', 'muskeln', 'geist', 'beweglichkeit', 'business', 'geld')
      and stat_id = canonical_stat_key)
    or
    (stat_kind = 'custom' and canonical_stat_key is null)
  )
);

create unique index arc_user_stats_canonical_unique
  on public.arc_user_stats(user_id, canonical_stat_key)
  where stat_kind = 'canonical';
create unique index arc_user_stats_active_order_idx
  on public.arc_user_stats(user_id, sort_order)
  where active;

create table public.arc_custom_tasks (
  user_id uuid not null references auth.users(id) on delete cascade,
  task_id text not null check (char_length(task_id) between 1 and 128),
  stat_id text not null,
  title text not null check (char_length(title) between 1 and 160),
  description text not null default '' check (char_length(description) <= 2000),
  tier smallint check (tier between 0 and 12),
  sort_order integer not null check (sort_order > 0),
  active boolean not null default true,
  deleted_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, task_id),
  unique (user_id, task_id, stat_id),
  foreign key (user_id, stat_id)
    references public.arc_user_stats(user_id, stat_id) on delete restrict,
  check ((active and deleted_at is null) or (not active))
);

create index arc_custom_tasks_stat_idx
  on public.arc_custom_tasks(user_id, stat_id, active, sort_order);

create table public.arc_preset_tasks (
  catalog_version text not null check (char_length(catalog_version) between 1 and 64),
  task_key text not null check (char_length(task_key) between 1 and 128),
  canonical_stat_key text not null
    check (canonical_stat_key in ('wissen', 'muskeln', 'geist', 'beweglichkeit', 'business', 'geld')),
  tier smallint not null check (tier between 0 and 12),
  sort_order integer not null check (sort_order > 0),
  title text not null check (char_length(title) > 0),
  description text not null,
  active boolean not null default true,
  content_hash text not null check (content_hash ~ '^[0-9a-f]{64}$'),
  created_at timestamptz not null default now(),
  primary key (catalog_version, task_key),
  unique (catalog_version, task_key, canonical_stat_key),
  unique (catalog_version, canonical_stat_key, sort_order)
);

create index arc_preset_tasks_selection_idx
  on public.arc_preset_tasks(catalog_version, canonical_stat_key, tier, active, sort_order);

create table public.arc_preset_task_exclusions (
  user_id uuid not null references auth.users(id) on delete cascade,
  catalog_version text not null,
  task_key text not null,
  excluded_at timestamptz not null default now(),
  primary key (user_id, catalog_version, task_key),
  foreign key (catalog_version, task_key)
    references public.arc_preset_tasks(catalog_version, task_key) on delete restrict
);

create table public.arc_daily_assignments (
  assignment_id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  arc_day date not null,
  stat_id text not null,
  task_source text not null check (task_source in ('preset', 'custom')),
  preset_catalog_version text,
  preset_task_key text,
  custom_task_id text,
  snapshot_title text not null check (char_length(snapshot_title) between 1 and 160),
  snapshot_description text not null check (char_length(snapshot_description) <= 2000),
  snapshot_tier smallint check (snapshot_tier between 0 and 12),
  snapshot_order integer not null check (snapshot_order > 0),
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  unique (user_id, stat_id, arc_day),
  unique (assignment_id, user_id, stat_id),
  foreign key (user_id, stat_id)
    references public.arc_user_stats(user_id, stat_id) on delete restrict,
  foreign key (preset_catalog_version, preset_task_key, stat_id)
    references public.arc_preset_tasks(catalog_version, task_key, canonical_stat_key) on delete restrict,
  foreign key (user_id, custom_task_id, stat_id)
    references public.arc_custom_tasks(user_id, task_id, stat_id) on delete restrict,
  check (
    (task_source = 'preset'
      and preset_catalog_version is not null
      and preset_task_key is not null
      and custom_task_id is null)
    or
    (task_source = 'custom'
      and preset_catalog_version is null
      and preset_task_key is null
      and custom_task_id is not null)
  )
);

create index arc_daily_assignments_user_day_idx
  on public.arc_daily_assignments(user_id, arc_day);

create table public.arc_progress_imports (
  import_id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  snapshot_hash text not null check (snapshot_hash ~ '^[0-9a-f]{64}$'),
  snapshot_schema_version integer not null check (snapshot_schema_version > 0),
  ownership_confidence text not null
    check (ownership_confidence in ('MODERATE', 'WEAK', 'NONE')),
  status text not null default 'pending'
    check (status in ('pending', 'importing', 'completed', 'failed', 'quarantined')),
  cutover_arc_day date not null,
  validation_summary jsonb not null default '{}'::jsonb,
  safe_progress_evidence jsonb,
  created_at timestamptz not null default now(),
  completed_at timestamptz,
  unique (user_id, snapshot_hash),
  unique (import_id, user_id),
  check ((status = 'completed' and completed_at is not null) or status <> 'completed')
);

create index arc_progress_imports_user_created_idx
  on public.arc_progress_imports(user_id, created_at desc);

create table public.arc_progress_events (
  event_id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  stat_id text not null,
  arc_day date not null,
  event_type text not null
    check (event_type in ('IMPORT_BASELINE', 'TASK_COMPLETION', 'DAILY_DECAY', 'ADMIN_ADJUSTMENT')),
  assignment_id uuid,
  import_id uuid,
  delta smallint not null,
  value_before smallint not null check (value_before between 0 and 100),
  value_after smallint not null check (value_after between 0 and 100),
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  foreign key (user_id, stat_id)
    references public.arc_user_stats(user_id, stat_id) on delete restrict,
  foreign key (assignment_id, user_id, stat_id)
    references public.arc_daily_assignments(assignment_id, user_id, stat_id) on delete restrict,
  foreign key (import_id, user_id)
    references public.arc_progress_imports(import_id, user_id) on delete restrict,
  check (value_after = value_before + delta),
  check (
    (event_type = 'TASK_COMPLETION' and assignment_id is not null and import_id is null)
    or (event_type = 'IMPORT_BASELINE' and assignment_id is null and import_id is not null)
    or (event_type in ('DAILY_DECAY', 'ADMIN_ADJUSTMENT') and assignment_id is null)
  )
);

create unique index arc_progress_events_completion_unique
  on public.arc_progress_events(assignment_id)
  where event_type = 'TASK_COMPLETION';
create index arc_progress_events_user_day_idx
  on public.arc_progress_events(user_id, arc_day, created_at);
create index arc_progress_events_user_stat_idx
  on public.arc_progress_events(user_id, stat_id, created_at desc);

create table public.arc_progress_daily_snapshots (
  user_id uuid not null references auth.users(id) on delete cascade,
  stat_id text not null,
  arc_day date not null,
  value smallint not null check (value between 0 and 100),
  source text not null check (source in ('server', 'legacy_unverified')),
  import_id uuid,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  primary key (user_id, stat_id, arc_day, source),
  foreign key (user_id, stat_id)
    references public.arc_user_stats(user_id, stat_id) on delete restrict,
  foreign key (import_id, user_id)
    references public.arc_progress_imports(import_id, user_id) on delete restrict,
  check (
    (source = 'legacy_unverified' and import_id is not null)
    or (source = 'server' and import_id is null)
  )
);

create index arc_progress_daily_snapshots_user_day_idx
  on public.arc_progress_daily_snapshots(user_id, arc_day);

