alter table public.arc_progress_state enable row level security;
alter table public.arc_user_stats enable row level security;
alter table public.arc_custom_tasks enable row level security;
alter table public.arc_preset_tasks enable row level security;
alter table public.arc_preset_task_exclusions enable row level security;
alter table public.arc_daily_assignments enable row level security;
alter table public.arc_progress_events enable row level security;
alter table public.arc_progress_imports enable row level security;
alter table public.arc_progress_daily_snapshots enable row level security;

create policy arc_progress_state_select_self on public.arc_progress_state
  for select to authenticated using (user_id = auth.uid());
create policy arc_user_stats_select_self on public.arc_user_stats
  for select to authenticated using (user_id = auth.uid());
create policy arc_custom_tasks_select_self on public.arc_custom_tasks
  for select to authenticated using (user_id = auth.uid());
create policy arc_preset_tasks_select_authenticated on public.arc_preset_tasks
  for select to authenticated using (true);
create policy arc_preset_task_exclusions_select_self on public.arc_preset_task_exclusions
  for select to authenticated using (user_id = auth.uid());
create policy arc_daily_assignments_select_self on public.arc_daily_assignments
  for select to authenticated using (user_id = auth.uid());
create policy arc_progress_events_select_self on public.arc_progress_events
  for select to authenticated using (user_id = auth.uid());
create policy arc_progress_imports_select_self on public.arc_progress_imports
  for select to authenticated using (user_id = auth.uid());
create policy arc_progress_daily_snapshots_select_self on public.arc_progress_daily_snapshots
  for select to authenticated using (user_id = auth.uid());

revoke all on table
  public.arc_progress_state,
  public.arc_user_stats,
  public.arc_custom_tasks,
  public.arc_preset_tasks,
  public.arc_preset_task_exclusions,
  public.arc_daily_assignments,
  public.arc_progress_events,
  public.arc_progress_imports,
  public.arc_progress_daily_snapshots
from public, anon, authenticated;

grant select on table
  public.arc_progress_state,
  public.arc_user_stats,
  public.arc_custom_tasks,
  public.arc_preset_tasks,
  public.arc_preset_task_exclusions,
  public.arc_daily_assignments,
  public.arc_progress_events,
  public.arc_progress_imports,
  public.arc_progress_daily_snapshots
to authenticated;

alter table public.arc_progress_state owner to postgres;
alter table public.arc_user_stats owner to postgres;
alter table public.arc_custom_tasks owner to postgres;
alter table public.arc_preset_tasks owner to postgres;
alter table public.arc_preset_task_exclusions owner to postgres;
alter table public.arc_daily_assignments owner to postgres;
alter table public.arc_progress_events owner to postgres;
alter table public.arc_progress_imports owner to postgres;
alter table public.arc_progress_daily_snapshots owner to postgres;

commit;
